import{_ as e,b as l,f as t,I as i}from"./chunks/framework.DYvp_Vyw.js";const b=JSON.parse('{"title":"Matlab学习笔记001 - MATLAB概述与运算基础","description":"","frontmatter":{"title":"Matlab学习笔记001 - MATLAB概述与运算基础","date":"2025-05-05T15:55:13.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-001.md","filePath":"posts/Matlab-Own-Study-001.md"}'),o={name:"posts/Matlab-Own-Study-001.md"};function r(h,a,d,n,A,c){return t(),l("div",null,a[0]||(a[0]=[i('<p>自己学习后整理的笔记（实时更新）</p><hr><h1 id="一-matlab特点" tabindex="-1">一. MATLAB特点: <a class="header-anchor" href="#一-matlab特点" aria-label="Permalink to &quot;一. MATLAB特点:&quot;">​</a></h1><h2 id="_1-数值计算和符号计算功能" tabindex="-1">1. 数值计算和符号计算功能 <a class="header-anchor" href="#_1-数值计算和符号计算功能" aria-label="Permalink to &quot;1. 数值计算和符号计算功能&quot;">​</a></h2><p>MATLAB的数值计算功能包括：矩阵运算、多项式和有理分式运算、数据统计分析、数值积分、优化处理等。符号计算将得到问题的解析解。</p><h2 id="_2-matlab语言" tabindex="-1">2.MATLAB语言 <a class="header-anchor" href="#_2-matlab语言" aria-label="Permalink to &quot;2.MATLAB语言&quot;">​</a></h2><p>MATLAB除了命令行的交互式操作以外，还可以程序方式工作。使用MATLAB可以很容易地实现C或FORTRAN语言的几乎全部功能，包括Windows图形用户界面的设计。</p><h2 id="_3-图形功能" tabindex="-1">3.图形功能 <a class="header-anchor" href="#_3-图形功能" aria-label="Permalink to &quot;3.图形功能&quot;">​</a></h2><p>MATLAB提供了两个层次的图形命令：一种是对图形句柄进行的低级图形命令，另一种是建立在低级图形命令之上的高级图形命令。利用MATLAB的高级图形命令可以轻而易举地绘制二维、三维乃至四维图形，并可进行图形和坐标的标识、视角和光照设计、色彩精细控制等等。</p><h2 id="_4-应用工具箱" tabindex="-1">4.应用工具箱 <a class="header-anchor" href="#_4-应用工具箱" aria-label="Permalink to &quot;4.应用工具箱&quot;">​</a></h2><p>基本部分和各种可选的工具箱。 基本部分中有数百个内部函数。 其工具箱分为两大类：功能性工具箱和学科性工具箱。 功能性工具箱主要用来扩充其符号计算功能、可视建模仿真功能及文字处理功能等。学科性工具箱专业性比较强，如控制系统工具箱、信号处理工具箱、神经网络工具箱、最优化工具箱、金融工具箱等，用户可以直接利用这些工具箱进行相关领域的科学研究。</p><h1 id="二-matlab运行环境" tabindex="-1">二.MATLAB运行环境 <a class="header-anchor" href="#二-matlab运行环境" aria-label="Permalink to &quot;二.MATLAB运行环境&quot;">​</a></h1><ul><li>硬件： 一般要求486以上的处理器、16MB以上内存、足够的的硬盘可用空间(随安装组件的多少而定)、CD-ROM驱动器、鼠标等。</li><li>软件： Windows 9x</li></ul><h1 id="三-matlab集成环境" tabindex="-1">三. MATLAB集成环境 <a class="header-anchor" href="#三-matlab集成环境" aria-label="Permalink to &quot;三. MATLAB集成环境&quot;">​</a></h1><blockquote><p>MATLAB 5.X是一个高度集成的语言环境，在该环境下既可以进行交互式的操作，又可以编写程序、运行程序并跟踪调试程序。</p></blockquote><h2 id="_1-matlab的启动" tabindex="-1">1. MATLAB的启动 <a class="header-anchor" href="#_1-matlab的启动" aria-label="Permalink to &quot;1. MATLAB的启动&quot;">​</a></h2><p>与一般的Windows 95程序一样，启动MATLAB有两种常见方法：</p><ul><li>(1)通过“开始”按钮，选择“程序”菜单项，然后打开“MATLAB”菜单中的“MATLAB”程序，就可启动MATLAB系统</li><li>(2) 利用Windows 95建立快捷方式的功能，将MATLAB程序以快捷方式放在桌面上。只要在桌面上双击该图标即可启动MATLAB</li></ul><h2 id="_2-matlab命令窗口" tabindex="-1">2. MATLAB命令窗口 <a class="header-anchor" href="#_2-matlab命令窗口" aria-label="Permalink to &quot;2. MATLAB命令窗口&quot;">​</a></h2><h3 id="_1-命令窗口的菜单栏" tabindex="-1">(1) 命令窗口的菜单栏 <a class="header-anchor" href="#_1-命令窗口的菜单栏" aria-label="Permalink to &quot;(1)  命令窗口的菜单栏&quot;">​</a></h3><p>菜单栏共包含File、Edit、Window和Help四项。</p><h4 id="file菜单项" tabindex="-1">File菜单项： <a class="header-anchor" href="#file菜单项" aria-label="Permalink to &quot;File菜单项：&quot;">​</a></h4><ul><li>New命令：用于建立M文件、图形窗口。</li><li>Open命令：打开一个已经建立的M文件。</li><li>Run Script命令：执行一个命令文件。</li><li>Load Workspace命令：将变量装入当前空间。</li><li>Save Workspace As命令：把当前工作空间的所有变量用后缀为.mat的文件保存起来。</li><li>Show Workspace命令：打开变量浏览器。</li><li>Set Path命令：打开MATLAB的路径浏览器。</li><li>Preferences命令：打开命令窗口的显示格式。</li><li>Print Setup命令：设置打印机的参数。</li><li>Print命令：打印和设置一些打印参数。</li><li>Print Selection命令：打印选中的内容。</li><li>Exit MATLAB命令：退出MATLAB系统。</li></ul><h4 id="edit菜单项" tabindex="-1">Edit菜单项： <a class="header-anchor" href="#edit菜单项" aria-label="Permalink to &quot;Edit菜单项：&quot;">​</a></h4><ul><li>Undo、Cut、Copy和Paste等命令：分别用于撤销上一次操作、剪切、复制和粘贴。</li><li>Clear命令：删除内容。</li><li>Select All命令：用于选定所有文本内容。</li><li>Clear Session命令：清除命令编辑区的全部内容，但并不删除工作空间中的变量。</li></ul><h4 id="help菜单项" tabindex="-1">Help菜单项: <a class="header-anchor" href="#help菜单项" aria-label="Permalink to &quot;Help菜单项:&quot;">​</a></h4><ul><li>Help Window命令：打开MATLAB的帮助窗口。</li><li>Help Tips命令：打开帮助窗口，并首先显示MATLAB的帮助系统的分类和使用方法。</li><li>Help Desk(HTML)命令：打开系统WWW浏览器，并显示MATLAB的帮助桌面。</li><li>Examples and Demos命令：可以通过演示MATLAB提供的例子来熟悉相关部分的用法。</li><li>About MATLAB命令：打开关于MATLAB的版本和版权等信息。</li><li>Subsribe命令：打开机器上的WWW浏览器，用户可过填写相关的表格来获得MathWorks公司的产品。</li></ul><h4 id="window菜单项" tabindex="-1">Window菜单项： <a class="header-anchor" href="#window菜单项" aria-label="Permalink to &quot;Window菜单项：&quot;">​</a></h4><p>利用Window菜单项可以查看目前MATLAB打开的所有窗口，并可选中某个窗口为当前窗口，从而实现在不同窗口之间的转换。</p><h3 id="_2-命令窗口的工具栏" tabindex="-1">(2)命令窗口的工具栏 <a class="header-anchor" href="#_2-命令窗口的工具栏" aria-label="Permalink to &quot;(2)命令窗口的工具栏&quot;">​</a></h3><blockquote><p>工具栏提供了一些命令按钮，使用命令按钮可使操作更快捷、更方便。</p></blockquote><h3 id="_3-命令窗口的命令编辑区" tabindex="-1">(3) 命令窗口的命令编辑区 <a class="header-anchor" href="#_3-命令窗口的命令编辑区" aria-label="Permalink to &quot;(3) 命令窗口的命令编辑区&quot;">​</a></h3><blockquote><p>命令编辑区用于输入命令和显示计算结果。键入命令并按下回车键后，MATLAB就会解释执行所输入的命令，并在命令后面给出计算结果。</p></blockquote><p>例如： 在MATLAB命令窗口输入命令：<br> a=[1,1.5,2,9,7；0,3.6,0.5,-4,4；7,10,-3,22,33；3,7,8.5,21,6；3,8,0,90,-20] 将显示一个5<code>*</code>5的矩阵。</p><h2 id="_3-matlab的退出" tabindex="-1">3. MATLAB的退出 <a class="header-anchor" href="#_3-matlab的退出" aria-label="Permalink to &quot;3. MATLAB的退出&quot;">​</a></h2><p>要退出MATLAB系统，有三种方法：</p><h3 id="_1-单击matlab命令窗口的-关闭-按钮。" tabindex="-1">(1)单击MATLAB命令窗口的“关闭”按钮。 <a class="header-anchor" href="#_1-单击matlab命令窗口的-关闭-按钮。" aria-label="Permalink to &quot;(1)单击MATLAB命令窗口的“关闭”按钮。&quot;">​</a></h3><h3 id="_2-在命令窗口file菜单中选exit-matlab命令。" tabindex="-1">(2)在命令窗口File菜单中选Exit MATLAB命令。 <a class="header-anchor" href="#_2-在命令窗口file菜单中选exit-matlab命令。" aria-label="Permalink to &quot;(2)在命令窗口File菜单中选Exit MATLAB命令。&quot;">​</a></h3><h3 id="_3-在matlab命令窗口输入exit和quit命令。" tabindex="-1">(3)在MATLAB命令窗口输入Exit和Quit命令。 <a class="header-anchor" href="#_3-在matlab命令窗口输入exit和quit命令。" aria-label="Permalink to &quot;(3)在MATLAB命令窗口输入Exit和Quit命令。&quot;">​</a></h3><p>在MATLAB中，变量名是以字母开头，后接字母、数字或下划线的字符序列，最多19个字符，且区分字母的大小写。MATLAB提供的标准函数名必须用小写字母。</p><h1 id="四-matlab运算量" tabindex="-1">四. MATLAB运算量 <a class="header-anchor" href="#四-matlab运算量" aria-label="Permalink to &quot;四. MATLAB运算量&quot;">​</a></h1><h2 id="_1-变量和赋值语句" tabindex="-1">１．变量和赋值语句 <a class="header-anchor" href="#_1-变量和赋值语句" aria-label="Permalink to &quot;１．变量和赋值语句&quot;">​</a></h2><p>MATLAB赋值语句有两种形式： (1) 变量=表达式<br> (2) 表达式 其中“表达式”是用运算符将有关运算量连接起来的式子，其结果是一个矩阵。 ［注］　第二种语句形式下，将表达式的值赋给MATLAB的<strong>永久变量ans</strong>。 如果在语句的最后加分号，那么，MATLAB仅仅执行赋值操作，不再显示运算的结果。在一条语句中，如果表达式太复杂，一行写不下，可以加上三个小黑点(续行符)并按下回车键，然后接下去再写。</p><blockquote><p>例如 s=1-1/2+1/3-1/4+1/5-1/6+1/7-…- 1/8+1/9-1/10+1/11-1/12;</p></blockquote><h2 id="_2-matlab表达式" tabindex="-1">２．MATLAB表达式 <a class="header-anchor" href="#_2-matlab表达式" aria-label="Permalink to &quot;２．MATLAB表达式&quot;">​</a></h2><h3 id="算术表达式" tabindex="-1">算术表达式 <a class="header-anchor" href="#算术表达式" aria-label="Permalink to &quot;算术表达式&quot;">​</a></h3><p>运算符有：＋(加)、－(减)、*(乘)、/(右除)、<code>\\</code>(左除)、^(乘方) 对于矩阵来说，左除和右除表示两种不同的除数矩阵和被除数矩阵的关系。</p><h3 id="关系表达式" tabindex="-1">关系表达式 <a class="header-anchor" href="#关系表达式" aria-label="Permalink to &quot;关系表达式&quot;">​</a></h3><p>运算符有：&lt;(小于)、&lt;=(小于或等于)、&gt;(大于)、&gt;=(大于或等于)、<code>==</code>(等于)、～=(不等于)</p><h3 id="逻辑表达式" tabindex="-1">逻辑表达式 <a class="header-anchor" href="#逻辑表达式" aria-label="Permalink to &quot;逻辑表达式&quot;">​</a></h3><p>运算符有：&amp;(与)、|(或)和～(非)</p><h3 id="运算法则" tabindex="-1">运算法则： <a class="header-anchor" href="#运算法则" aria-label="Permalink to &quot;运算法则：&quot;">​</a></h3><p>(1)在逻辑运算中，确认非零元素为真，用1表示，零元素为假，用0表示。 (2)参与逻辑运算的可以是两个标量、两个同维矩阵或参与逻辑运算的元素一个为标量，另一个为矩阵。 (３)在算术、关系、逻辑运算中，算术运算优先级最高，逻辑运算优先级最低。</p><h1 id="五-矩阵运算" tabindex="-1">五. 矩阵运算 <a class="header-anchor" href="#五-矩阵运算" aria-label="Permalink to &quot;五. 矩阵运算&quot;">​</a></h1><blockquote><p>矩阵是MATLAB最基本的数据对象，MATLAB的大部分运算或命令都是在矩阵运算的意义下执行的。在MATLAB中，不需对矩阵的维数和类型进行说明，MATLAB会根据用户所输入的内容自动进行配置。</p></blockquote><h2 id="_1-建立矩阵" tabindex="-1">１．建立矩阵 <a class="header-anchor" href="#_1-建立矩阵" aria-label="Permalink to &quot;１．建立矩阵&quot;">​</a></h2><p>建立矩阵可以用：直接输入法、利用函数建立矩阵和利用M文件建立矩阵。 直接输入法：将矩阵的元素用方括号括起来，按矩阵行的顺序输入各元素，同一行的各元素之间用空格或逗号分隔，不同行的元素之间用分号分隔。(也可以用回车键代替分号)</p><p><strong>利用函数建立数值矩阵</strong>：MATLAB提供了许多生成和操作矩阵的函数，可以利用它们去建立矩阵。 例如:reshape函数和diag函数等。 reshape函数用于建立数值矩阵。 diag函数用于产生对角阵。</p><p><strong>利用M文件建立矩阵</strong>：对于比较大且比较复杂的矩阵，可以为它专门建立一个M文件。其步骤为： 第一步：使用编辑程序输入文件内容。 第二步：把输入的内容以纯文本方式存盘(设文件名为mymatrix.m)。 第三步：在MATLAB命令窗口中输入mymatrix，就会自动建立一个名为AM的矩阵，可供以后显示和调用。</p><h2 id="_2-冒号表达式" tabindex="-1">２．冒号表达式 <a class="header-anchor" href="#_2-冒号表达式" aria-label="Permalink to &quot;２．冒号表达式&quot;">​</a></h2><p>在MATLAB中，冒号是一个重要的运算符。利用它可以产生向量，还可用来拆分矩阵。冒号表达式的一般格式是： e1:e2:e3其中e1为初始值，e2为步长，e3为终止值。冒号表达式可产生一个由e1开始到e3结束，以步长e2自增的行向量。</p><blockquote><p>类似Python中的切片。</p></blockquote><h2 id="_3-matlab常用数学函数" tabindex="-1">３．MATLAB常用数学函数 <a class="header-anchor" href="#_3-matlab常用数学函数" aria-label="Permalink to &quot;３．MATLAB常用数学函数&quot;">​</a></h2><p>MATLAB提供了许多数学函数，函数的自变量规定为矩阵变量，运算法则是将函数逐项作用于矩阵的元素上，因而运算的结果是一个与自变量同维数的矩阵。 例如：　 A= <code>[1 2 3;4 5 6]</code> 　　　　B=<code>fix(pi*A)</code> 　　　　C=<code>cos(pi*B)</code></p><h2 id="_4-矩阵的基本运算" tabindex="-1">４．矩阵的基本运算 <a class="header-anchor" href="#_4-矩阵的基本运算" aria-label="Permalink to &quot;４．矩阵的基本运算&quot;">​</a></h2><p>（１）矩阵转置 （２）矩阵加和减 （３）矩阵乘法 （４）矩阵除法 <code>A\\b=inv(A)*b</code> （５）矩阵的乘方 <code>a^2</code></p><h2 id="_5-建立矩阵的函数" tabindex="-1">５．建立矩阵的函数 <a class="header-anchor" href="#_5-建立矩阵的函数" aria-label="Permalink to &quot;５．建立矩阵的函数&quot;">​</a></h2><p>常用函数有： <code>eye(size(A))</code> 产生与A矩阵同阶的单位矩阵 <code>zeros(m,n)</code> 产生0矩阵 <code>ones(m,n)</code> 产生幺矩阵 <code>rand (m,n)</code> 产生随机元素的矩阵 <code>Size(a)</code> 返回包含两个元素的向量。 <code>Length(a)</code> 返回向量的最大者。</p><h2 id="_6-数组运算" tabindex="-1">６．数组运算 <a class="header-anchor" href="#_6-数组运算" aria-label="Permalink to &quot;６．数组运算&quot;">​</a></h2><p>（1） 数组的加和减 （2） 数组的乘和除 （3） 数组的乘方</p><hr>',71)]))}const u=e(o,[["render",r]]);export{b as __pageData,u as default};
